import React, {useEffect, useState } from "react"
import { graphql } from 'gatsby'
import Layout from "../components/Layout"
import BANNER_IMG from '../images/banner.jpg';
import ProductCard from "../shop/product-card";
import { Link } from "gatsby"
import HrWithText from "../components/divider"
import Item from "../components/item"
import Seo from "../components/seo"

const Products = ({ products }) => {
	console.log( products );
    return (
     <div className="product-grid">
      { products.map( p => ( <ProductCard
      key={p.id}
      title={p.title}
      price={ p.price }
      currency={ p.currency }
      description={p.description}
      image={p.imageUrl}
      merchant={p.brand || "Store"}
      url={`/products/${p.slug}`}
      badge={p.salePrice ? "Sale" : null}
      originalPrice={
        p.salePrice ? `${p.price} ${p.currency}` : null
      }
      price={
        p.salePrice
          ? `${p.salePrice}`
          : `${p.price}`
      }
    />) ) }
    </div> );
}
	
const HomePage = ({ data }) => {
  const products = data.allMerchantProduct.nodes;
  const latestPost = data.latestPost.nodes[0];

  return (
    <Layout>
      <img src={ BANNER_IMG } style={{width:"100%"}} alt="wisdel.uk" className="banner"/>
      <HrWithText text="Latest" />
      <Link to={latestPost.frontmatter.slug } ><Item title={ latestPost.frontmatter.title } date={ latestPost.frontmatter.date } body={ latestPost.excerpt  } /></Link>
      <HrWithText text="Products" />
      <Products products={ products } />
    </Layout>
  )
}

export const query = graphql`
  {
    allMerchantProduct(
      sort: { fields: title }
      limit: 3
    ) {
      nodes {
        id
        title
        slug
        price
        currency
        imageUrl
        description
      }
    }

    latestPost: allMarkdownRemark(
      filter: { frontmatter: { slug: { glob: "*/latest/*" } } }
      sort: {frontmatter: {date: DESC}}
      limit: 1
    ) {
      nodes {
        id
        excerpt(pruneLength: 300)
        frontmatter {
          title
          date(formatString: "Y-MM-DD")
          slug
        }
      }
    }
  }
`;




export default HomePage

export function Head() {
  const schema = {
    "@context": "https://schema.org",
    "@graph": [
      {
        "@type": "WebSite",
        "@id": "https://lacdael.github.io/lacdael/#website",
        url: "https://lacdael.github.io/lacdael/",
        name: "Wisdel.uk",
        description: "Embedded electronics, control systems and practical hardware projects.",
        inLanguage: "en-GB",
      },
      {
        "@type": "Organization",
        "@id": "https://lacdael.github.io/lacdael/#organization",
        name: "Wisdel.uk",
        url: "https://lacdael.github.io/lacdael/",
        logo: "https://lacdael.github.io/lacdael/logo-text.png",
        founder: { "@id": "https://lacdael.github.io/lacdael/contact/#person" },
      },
    ],
  }

  return (
    <Seo
      title="Embedded Electronics and Control Systems"
      description="Wisdel.uk builds and documents embedded electronics, control systems, maker hardware and smart agriculture technologies."
      image="/banner.jpg"
      imageAlt="Wisdel.uk embedded electronics and control systems"
      imageWidth={1200}
      imageHeight={630}
      schemaMarkup={schema}
      pathname="/"
    />
  )
}
